import 'package:flutter/material.dart';

class UnsavedChangesConfirmation extends StatelessWidget {
  const UnsavedChangesConfirmation({
    super.key,
    required this.onSave,
    required this.onDiscard,
    required this.onCancel,
  });

  final VoidCallback onSave;
  final VoidCallback onDiscard;
  final VoidCallback onCancel;

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: const Text('Unsaved Changes'),
      content: const Text(
        'You have unsaved changes. Do you want to save them before leaving?',
      ),
      actions: [
        TextButton(
          onPressed: onCancel,
          child: const Text('Cancel'),
        ),
        TextButton(
          onPressed: onDiscard,
          child: const Text('Discard'),
        ),
        FilledButton(
          onPressed: onSave,
          child: const Text('Save'),
        ),
      ],
    );
  }
}

class ScreenWithUnsavedChanges extends StatefulWidget {
  const ScreenWithUnsavedChanges({super.key});

  @override
  State<ScreenWithUnsavedChanges> createState() =>
      _ScreenWithUnsavedChangesState();
}

class _ScreenWithUnsavedChangesState extends State<ScreenWithUnsavedChanges> {
  bool _hasUnsavedChanges = false;

  @override
  Widget build(BuildContext context) {
    return WillPopScope(
      onWillPop: _onWillPop,
      child: Scaffold(
        appBar: AppBar(
          title: const Text('Screen with Unsaved Changes'),
        ),
        body: Center(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                'Has unsaved changes: $_hasUnsavedChanges',
                style: Theme.of(context).textTheme.titleMedium,
              ),
              const SizedBox(height: 16),
              ElevatedButton(
                onPressed: () {
                  setState(() {
                    _hasUnsavedChanges = !_hasUnsavedChanges;
                  });
                },
                child: const Text('Toggle Unsaved Changes'),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Future<bool> _onWillPop() async {
    if (!_hasUnsavedChanges) {
      return true;
    }

    final result = await showDialog<bool>(
      context: context,
      builder: (context) => UnsavedChangesConfirmation(
        onSave: () => Navigator.of(context).pop(true),
        onDiscard: () => Navigator.of(context).pop(true),
        onCancel: () => Navigator.of(context).pop(false),
      ),
    );

    return result ?? false;
  }
}
