import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

class HardwareKeyListener extends StatefulWidget {
  const HardwareKeyListener({super.key});

  @override
  State<HardwareKeyListener> createState() => _HardwareKeyListenerState();
}

class _HardwareKeyListenerState extends State<HardwareKeyListener> {
  late FocusNode _focusNode;

  @override
  void initState() {
    super.initState();
    _focusNode = FocusNode();
    _focusNode.requestFocus();
  }

  @override
  void dispose() {
    _focusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Focus(
      focusNode: _focusNode,
      autofocus: true,
      onKeyEvent: (node, event) {
        if (event is KeyDownEvent) {
          debugPrint('Key down: ${event.logicalKey}');
        }
        return KeyEventResult.handled;
